import { useEffect, useRef, useState, useCallback } from 'react';
import { AppState, type AppStateStatus } from 'react-native';
import { useNavigation } from 'expo-router';
import { useAudioPlayer, type AudioPlayerState } from './useAudioPlayer';
import type { PageData } from '@/types';

/**
 * Audio state tracking user's intent for playback
 * Separate from actual playback state to handle transitions properly
 */
type AudioState = {
  isNarrationActive: boolean;
  isSoundscapeActive: boolean;
  narrationUrl: string | null;
  soundscapeUrl: string | null;
  isTransitioning: boolean;
};

/**
 * Props for the useAudioManager hook
 */
export interface UseAudioManagerProps {
  pageData: PageData | undefined;
  bookId: string;
  pageNumber: number;
}

/**
 * Return type for the useAudioManager hook
 */
export interface UseAudioManagerReturn {
  // State
  isNarrationActive: boolean;
  isSoundscapeActive: boolean;
  narrationState: AudioPlayerState;
  soundscapeState: AudioPlayerState;
  isTransitioning: boolean;
  isDucked: boolean;
  soundscapeVolume: number;

  // Actions
  toggleNarration: () => Promise<void>;
  toggleSoundscape: () => Promise<void>;
  toggleBoth: (enabled: boolean) => Promise<void>;

  // Cleanup
  cleanup: () => Promise<void>;
}

/** Audio configuration constants */
const AUDIO_CONFIG = {
  SOUNDSCAPE: {
    NORMAL_VOLUME: 0.6,
    DUCKED_VOLUME: 0.15,
    FADE_IN_DURATION: 500,
    FADE_OUT_DURATION: 300,
  },
  NARRATION: {
    NORMAL_VOLUME: 1.0,
  },
} as const;

/**
 * Extract narration URL from page data
 * Checks both assignments array and legacy narrationUrl field
 */
function getNarrationUrl(pageData: PageData | undefined): string | null {
  if (!pageData) return null;

  const narrationAssignment = pageData.assignments?.find((a) => a.audioType === 'narration');
  return narrationAssignment?.audioUrl || pageData.narrationUrl || null;
}

/**
 * Extract soundscape URL from page data
 * Checks assignments array for soundscape type
 */
function getSoundscapeUrl(pageData: PageData | undefined): string | null {
  if (!pageData) return null;

  const soundscapeAssignment = pageData.assignments?.find((a) => a.audioType === 'soundscape');
  return soundscapeAssignment?.audioUrl || null;
}

/**
 * Custom hook for managing audio playback in the reader
 *
 * Handles:
 * - Page transitions with proper audio cleanup and loading
 * - Simultaneous narration and soundscape playback with ducking
 * - Audio state management and transitions
 * - Proper cleanup on unmount
 *
 * @example
 * ```tsx
 * const {
 *   isNarrationActive,
 *   isSoundscapeActive,
 *   toggleNarration,
 *   toggleSoundscape,
 *   cleanup
 * } = useAudioManager({ pageData, bookId, pageNumber });
 * ```
 */
export function useAudioManager({
  pageData,
  bookId,
  pageNumber,
}: UseAudioManagerProps): UseAudioManagerReturn {
  const navigation = useNavigation();

  const {
    narrationState,
    loadNarration,
    playNarration,
    pauseNarration,
    soundscapeState,
    loadSoundscape,
    playSoundscape,
    pauseSoundscape,
    setSoundscapeVolume,
    crossfadeSoundscape,
    cleanup: cleanupAudioPlayer,
  } = useAudioPlayer();

  // Track mount state to prevent state updates after unmount
  const isMountedRef = useRef(true);

  // Fade interval ref for volume ducking
  const fadeIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Ducking state management
  const [isDucked, setIsDucked] = useState(false);
  const [soundscapeVolume, setSoundscapeVolumeState] = useState<number>(AUDIO_CONFIG.SOUNDSCAPE.NORMAL_VOLUME);
  const intendedVolumeRef = useRef(AUDIO_CONFIG.SOUNDSCAPE.NORMAL_VOLUME);
  const duckingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Track previous page number to detect page changes
  const prevPageNumberRef = useRef<number>(pageNumber);

  // Track subscriptions and timers for cleanup
  const appStateSubscriptionRef = useRef<ReturnType<typeof AppState.addEventListener> | null>(null);
  const navigationUnsubscribeRef = useRef<(() => void) | null>(null);
  const transitionTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Audio state - tracks user's intent for playback
  const [audioState, setAudioState] = useState<AudioState>({
    isNarrationActive: false,
    isSoundscapeActive: false,
    narrationUrl: null,
    soundscapeUrl: null,
    isTransitioning: false,
  });

  /**
   * Safely update audio state only if component is still mounted
   */
  const safeSetAudioState = useCallback((updates: Partial<AudioState>) => {
    if (isMountedRef.current) {
      setAudioState((prev) => ({ ...prev, ...updates }));
    }
  }, []);

  /**
   * Fade soundscape volume to target level
   * Uses interval-based animation for smooth transitions
   */
  const fadeSoundscapeVolume = useCallback(async (targetVolume: number, duration: number) => {
    const steps = 20;
    const stepDuration = duration / steps;
    const currentVolume = soundscapeVolume;
    const volumeStep = (targetVolume - currentVolume) / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) {
      clearInterval(fadeIntervalRef.current);
      fadeIntervalRef.current = null;
    }

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(() => {
        currentStep++;
        const newVolume = currentVolume + volumeStep * currentStep;
        const clampedVolume = Math.max(0, Math.min(1, newVolume));

        setSoundscapeVolume(clampedVolume).catch(() => {
          // Ignore errors during fade
        });

        if (isMountedRef.current) {
          setSoundscapeVolumeState(clampedVolume);
        }

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) {
            clearInterval(fadeIntervalRef.current);
            fadeIntervalRef.current = null;
          }
          if (isMountedRef.current) {
            setSoundscapeVolumeState(targetVolume);
          }
          resolve();
        }
      }, stepDuration);
    });
  }, [soundscapeVolume, setSoundscapeVolume]);

  /**
   * Handle page transitions
   * This is the core logic that fixes the page transition bugs:
   * 1. Stops current narration immediately
   * 2. Loads new narration URL if available
   * 3. Auto-plays new narration if narration was active
   * 4. Crossfades soundscape if active
   * 5. Sets transitioning flag during the process
   */
  useEffect(() => {
    const handlePageTransition = async () => {
      if (!pageData) return;

      // Only run on actual page changes, not initial load
      const isPageChange = prevPageNumberRef.current !== pageNumber;
      prevPageNumberRef.current = pageNumber;

      const narrationUrl = getNarrationUrl(pageData);
      const soundscapeUrl = getSoundscapeUrl(pageData);

      safeSetAudioState({
        isTransitioning: true,
        narrationUrl,
        soundscapeUrl,
      });

      try {
        // Step 1: Stop current narration immediately
        if (narrationState.isPlaying) {
          await pauseNarration();
        }

        // Step 2: Load new narration if URL available
        if (narrationUrl) {
          await loadNarration(narrationUrl);

          // Step 3: Auto-play if narration was active and this is a page change
          // or if narration was already active (user expects continuous playback)
          if (audioState.isNarrationActive && isPageChange) {
            await playNarration();
          }
        }

        // Step 4: Handle soundscape transition
        if (soundscapeUrl && audioState.isSoundscapeActive) {
          // Crossfade to new soundscape
          await crossfadeSoundscape(soundscapeUrl);
        } else if (!soundscapeUrl && audioState.isSoundscapeActive) {
          // No soundscape for this page - pause current
          await pauseSoundscape();
        } else if (soundscapeUrl && !audioState.isSoundscapeActive && isPageChange) {
          // Load but don't play - user hasn't activated soundscape
          await loadSoundscape(soundscapeUrl);
        }
      } catch (error) {
        // Log error but don't crash
        if (__DEV__) {
          console.error('Audio transition error:', error);
        }
      } finally {
        safeSetAudioState({ isTransitioning: false });
      }
    };

    handlePageTransition();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pageNumber, pageData?.id, bookId]);

  /**
   * Smart ducking effect with delay to avoid "pumping" effect
   * When narration starts playing: fade soundscape to DUCKED_VOLUME
   * When narration stops: restore soundscape to NORMAL_VOLUME after brief delay
   */
  useEffect(() => {
    // Clear any pending ducking operations
    if (duckingTimeoutRef.current) {
      clearTimeout(duckingTimeoutRef.current);
      duckingTimeoutRef.current = null;
    }

    if (audioState.isNarrationActive && narrationState.isPlaying) {
      // Narration started - duck soundscape
      if (!isDucked && audioState.isSoundscapeActive && soundscapeState.isPlaying) {
        setIsDucked(true);
        fadeSoundscapeVolume(AUDIO_CONFIG.SOUNDSCAPE.DUCKED_VOLUME, AUDIO_CONFIG.SOUNDSCAPE.FADE_OUT_DURATION);
      }
    } else {
      // Narration stopped/paused - restore soundscape after brief delay
      if (isDucked) {
        duckingTimeoutRef.current = setTimeout(() => {
          if (isMountedRef.current) {
            setIsDucked(false);
            fadeSoundscapeVolume(AUDIO_CONFIG.SOUNDSCAPE.NORMAL_VOLUME, AUDIO_CONFIG.SOUNDSCAPE.FADE_IN_DURATION);
          }
        }, 500); // Small delay to avoid "pumping" effect
      }
    }

    return () => {
      if (duckingTimeoutRef.current) {
        clearTimeout(duckingTimeoutRef.current);
        duckingTimeoutRef.current = null;
      }
    };
  }, [
    narrationState.isPlaying,
    audioState.isNarrationActive,
    audioState.isSoundscapeActive,
    soundscapeState.isPlaying,
    isDucked,
    fadeSoundscapeVolume,
  ]);

  /**
   * Toggle narration playback
   * Handles edge cases like missing URLs and loading states
   */
  const toggleNarration = useCallback(async () => {
    const narrationUrl = getNarrationUrl(pageData);

    if (!narrationUrl) {
      // No narration available for this page
      return;
    }

    if (audioState.isNarrationActive) {
      // Stop narration
      await pauseNarration();
      safeSetAudioState({ isNarrationActive: false });
    } else {
      // Start narration
      if (!narrationState.isPlaying) {
        // Need to load first if not already loaded
        if (audioState.narrationUrl !== narrationUrl) {
          await loadNarration(narrationUrl);
        }
        await playNarration();
      }
      safeSetAudioState({ isNarrationActive: true });
    }
  }, [
    pageData,
    audioState.isNarrationActive,
    audioState.narrationUrl,
    narrationState.isPlaying,
    loadNarration,
    playNarration,
    pauseNarration,
    safeSetAudioState,
  ]);

  /**
   * Navigation cleanup - stop audio before leaving screen
   * Prevents audio from continuing when user navigates away
   */
  useEffect(() => {
    const unsubscribe = navigation.addListener('beforeRemove', () => {
      // Stop all audio before navigation
      pauseNarration();
      pauseSoundscape();

      // Clear any pending operations
      if (transitionTimeoutRef.current) {
        clearTimeout(transitionTimeoutRef.current);
        transitionTimeoutRef.current = null;
      }
      if (duckingTimeoutRef.current) {
        clearTimeout(duckingTimeoutRef.current);
        duckingTimeoutRef.current = null;
      }
    });

    navigationUnsubscribeRef.current = unsubscribe;

    return () => {
      unsubscribe();
      navigationUnsubscribeRef.current = null;
    };
  }, [navigation, pauseNarration, pauseSoundscape]);

  /**
   * App State handling (background/foreground)
   * Pauses audio when app goes to background
   */
  useEffect(() => {
    const subscription = AppState.addEventListener('change', (nextAppState: AppStateStatus) => {
      if (nextAppState === 'background') {
        // Pause audio when app goes to background
        pauseNarration();
        pauseSoundscape();
        if (isMountedRef.current) {
          safeSetAudioState({
            isNarrationActive: false,
            isSoundscapeActive: false,
          });
        }
      }
    });

    appStateSubscriptionRef.current = subscription;

    return () => {
      subscription.remove();
      appStateSubscriptionRef.current = null;
    };
  }, [pauseNarration, pauseSoundscape, safeSetAudioState]);

  /**
   * Toggle soundscape playback
   * Handles crossfading and volume restoration
   */
  const toggleSoundscape = useCallback(async () => {
    const soundscapeUrl = getSoundscapeUrl(pageData);

    if (!soundscapeUrl) {
      // No soundscape available for this page
      return;
    }

    if (audioState.isSoundscapeActive) {
      // Stop soundscape
      await pauseSoundscape();
      safeSetAudioState({ isSoundscapeActive: false });
    } else {
      // Start soundscape
      if (!soundscapeState.isPlaying) {
        // Need to load first if not already loaded
        if (audioState.soundscapeUrl !== soundscapeUrl) {
          await loadSoundscape(soundscapeUrl);
        }
        await playSoundscape();

        // Apply ducking if narration is also playing
        if (audioState.isNarrationActive && narrationState.isPlaying) {
          await setSoundscapeVolume(AUDIO_CONFIG.SOUNDSCAPE.DUCKED_VOLUME);
        } else {
          await setSoundscapeVolume(AUDIO_CONFIG.SOUNDSCAPE.NORMAL_VOLUME);
        }
      }
      safeSetAudioState({ isSoundscapeActive: true });
    }
  }, [
    pageData,
    audioState.isSoundscapeActive,
    audioState.soundscapeUrl,
    audioState.isNarrationActive,
    soundscapeState.isPlaying,
    narrationState.isPlaying,
    loadSoundscape,
    playSoundscape,
    pauseSoundscape,
    setSoundscapeVolume,
    safeSetAudioState,
  ]);

  /**
   * Toggle both narration and soundscape together
   * Useful for enabling/disabling all audio at once
   */
  const toggleBoth = useCallback(async (enabled: boolean) => {
    safeSetAudioState({ isTransitioning: true });

    const narrationUrl = getNarrationUrl(pageData);
    const soundscapeUrl = getSoundscapeUrl(pageData);

    try {
      if (enabled) {
        // Enable both
        if (narrationUrl && !audioState.isNarrationActive) {
          if (audioState.narrationUrl !== narrationUrl) {
            await loadNarration(narrationUrl);
          }
          await playNarration();
          safeSetAudioState({ isNarrationActive: true });
        }
        if (soundscapeUrl && !audioState.isSoundscapeActive) {
          if (audioState.soundscapeUrl !== soundscapeUrl) {
            await loadSoundscape(soundscapeUrl);
          }
          await playSoundscape();
          // Duck if narration is playing
          if (audioState.isNarrationActive && narrationState.isPlaying) {
            await setSoundscapeVolume(AUDIO_CONFIG.SOUNDSCAPE.DUCKED_VOLUME);
          }
          safeSetAudioState({ isSoundscapeActive: true });
        }
      } else {
        // Disable both
        if (audioState.isNarrationActive) {
          await pauseNarration();
          safeSetAudioState({ isNarrationActive: false });
        }
        if (audioState.isSoundscapeActive) {
          await pauseSoundscape();
          safeSetAudioState({ isSoundscapeActive: false });
        }
      }
    } finally {
      safeSetAudioState({ isTransitioning: false });
    }
  }, [
    pageData,
    audioState.isNarrationActive,
    audioState.isSoundscapeActive,
    audioState.narrationUrl,
    audioState.soundscapeUrl,
    narrationState.isPlaying,
    loadNarration,
    playNarration,
    pauseNarration,
    loadSoundscape,
    playSoundscape,
    pauseSoundscape,
    setSoundscapeVolume,
    safeSetAudioState,
  ]);

  /**
   * Comprehensive cleanup - bulletproof version
   * Stops all playback, clears all timers/subscriptions, and resets state
   */
  const cleanup = useCallback(async () => {
    // Stop all playback immediately
    await pauseNarration();
    await pauseSoundscape();

    // Clear all timers
    if (fadeIntervalRef.current) {
      clearInterval(fadeIntervalRef.current);
      fadeIntervalRef.current = null;
    }
    if (duckingTimeoutRef.current) {
      clearTimeout(duckingTimeoutRef.current);
      duckingTimeoutRef.current = null;
    }
    if (transitionTimeoutRef.current) {
      clearTimeout(transitionTimeoutRef.current);
      transitionTimeoutRef.current = null;
    }

    // Reset states only if still mounted
    if (isMountedRef.current) {
      safeSetAudioState({
        isNarrationActive: false,
        isSoundscapeActive: false,
        isTransitioning: false,
      });
      setIsDucked(false);
    }

    // Cleanup audio player
    await cleanupAudioPlayer();
  }, [pauseNarration, pauseSoundscape, cleanupAudioPlayer, safeSetAudioState]);

  /**
   * Component lifecycle management
   * Bulletproof cleanup on unmount - ensures audio NEVER continues after exit
   */
  useEffect(() => {
    isMountedRef.current = true;

    return () => {
      isMountedRef.current = false;

      // Immediately stop all audio - don't wait for async
      pauseNarration().catch(() => {
        // Ignore errors during cleanup
      });
      pauseSoundscape().catch(() => {
        // Ignore errors during cleanup
      });

      // Clear all pending operations immediately
      if (transitionTimeoutRef.current) {
        clearTimeout(transitionTimeoutRef.current);
        transitionTimeoutRef.current = null;
      }
      if (duckingTimeoutRef.current) {
        clearTimeout(duckingTimeoutRef.current);
        duckingTimeoutRef.current = null;
      }
      if (fadeIntervalRef.current) {
        clearInterval(fadeIntervalRef.current);
        fadeIntervalRef.current = null;
      }

      // Remove listeners
      if (navigationUnsubscribeRef.current) {
        navigationUnsubscribeRef.current();
        navigationUnsubscribeRef.current = null;
      }
      if (appStateSubscriptionRef.current) {
        appStateSubscriptionRef.current.remove();
        appStateSubscriptionRef.current = null;
      }

      // Final cleanup after brief delay to ensure stops complete
      setTimeout(() => {
        cleanupAudioPlayer().catch(() => {
          // Ignore errors during final cleanup
        });
      }, 100);
    };
  }, [pauseNarration, pauseSoundscape, cleanupAudioPlayer]);

  return {
    isNarrationActive: audioState.isNarrationActive,
    isSoundscapeActive: audioState.isSoundscapeActive,
    narrationState,
    soundscapeState,
    isTransitioning: audioState.isTransitioning,
    isDucked,
    soundscapeVolume,
    toggleNarration,
    toggleSoundscape,
    toggleBoth,
    cleanup,
  };
}

import { useRef, useCallback, useEffect, useState } from 'react';
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

export type AudioPlayerState = {
  isPlaying: boolean;
  positionMs: number;
  durationMs: number;
};

type UseAudioPlayerReturn = {
  // Narration
  narrationState: AudioPlayerState;
  loadNarration: (uri: string) => Promise<void>;
  playNarration: () => Promise<void>;
  pauseNarration: () => Promise<void>;
  seekNarration: (positionMs: number) => Promise<void>;
  setNarrationVolume: (volume: number) => Promise<void>;
  // Soundscape
  soundscapeState: AudioPlayerState;
  loadSoundscape: (uri: string) => Promise<void>;
  playSoundscape: () => Promise<void>;
  pauseSoundscape: () => Promise<void>;
  setSoundscapeVolume: (volume: number) => Promise<void>;
  // Crossfade
  crossfadeSoundscape: (newUri: string, duration?: number) => Promise<void>;
  fadeOutSoundscape: (duration?: number) => Promise<void>;
  // Cleanup
  cleanup: () => Promise<void>;
};

export function useAudioPlayer(): UseAudioPlayerReturn {
  const narrationRef = useRef<AudioPlayer | null>(null);
  const soundscapeRef = useRef<AudioPlayer | null>(null);
  const narrationSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
  const soundscapeSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
  const fadeIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // Track the current soundscape volume for fade calculations
  const soundscapeVolumeRef = useRef<number>(0.6);

  const [narrationState, setNarrationState] = useState<AudioPlayerState>({
    isPlaying: false,
    positionMs: 0,
    durationMs: 0,
  });

  const [soundscapeState, setSoundscapeState] = useState<AudioPlayerState>({
    isPlaying: false,
    positionMs: 0,
    durationMs: 0,
  });

  // Configure audio mode for background playback
  useEffect(() => {
    setAudioModeAsync({
      playsInSilentMode: true,
      interruptionMode: 'mixWithOthers',
      allowsRecording: false,
    });
  }, []);

  // Narration controls
  const loadNarration = useCallback(async (uri: string) => {
    // Clean up previous narration player
    if (narrationSubRef.current) {
      narrationSubRef.current.remove();
      narrationSubRef.current = null;
    }
    if (narrationRef.current) {
      narrationRef.current.remove();
      narrationRef.current = null;
    }

    const player = createAudioPlayer({ uri });

    // Subscribe to status updates for word-sync (high frequency)
    narrationSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
      setNarrationState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    narrationRef.current = player;
  }, []);

  const playNarration = useCallback(async () => {
    narrationRef.current?.play();
  }, []);

  const pauseNarration = useCallback(async () => {
    narrationRef.current?.pause();
  }, []);

  const seekNarration = useCallback(async (positionMs: number) => {
    narrationRef.current?.seekTo(positionMs / 1000);
  }, []);

  const setNarrationVolume = useCallback(async (volume: number) => {
    if (narrationRef.current) {
      narrationRef.current.volume = volume;
    }
  }, []);

  // Soundscape controls
  const loadSoundscape = useCallback(async (uri: string) => {
    // Clean up previous soundscape player
    if (soundscapeSubRef.current) {
      soundscapeSubRef.current.remove();
      soundscapeSubRef.current = null;
    }
    if (soundscapeRef.current) {
      soundscapeRef.current.remove();
      soundscapeRef.current = null;
    }

    const player = createAudioPlayer({ uri });
    player.loop = true;
    player.volume = 0.6;
    soundscapeVolumeRef.current = 0.6;

    soundscapeSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
      setSoundscapeState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    soundscapeRef.current = player;
  }, []);

  const playSoundscape = useCallback(async () => {
    soundscapeRef.current?.play();
  }, []);

  const pauseSoundscape = useCallback(async () => {
    soundscapeRef.current?.pause();
  }, []);

  const setSoundscapeVolume = useCallback(async (volume: number) => {
    if (soundscapeRef.current) {
      soundscapeRef.current.volume = volume;
      soundscapeVolumeRef.current = volume;
    }
  }, []);

  // Fade out over duration
  const fadeOutSoundscape = useCallback(async (duration: number = 3000) => {
    const player = soundscapeRef.current;
    if (!player) return;

    const startVolume = soundscapeVolumeRef.current;
    const steps = 20;
    const stepDuration = duration / steps;
    const volumeStep = startVolume / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(() => {
        currentStep++;
        const newVolume = Math.max(0, startVolume - volumeStep * currentStep);
        player.volume = newVolume;
        soundscapeVolumeRef.current = newVolume;

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
          player.pause();
          resolve();
        }
      }, stepDuration);
    });
  }, []);

  // Crossfade: fade out current, load new, fade in
  const crossfadeSoundscape = useCallback(async (newUri: string, duration: number = 1500) => {
    const oldPlayer = soundscapeRef.current;
    const oldSub = soundscapeSubRef.current;

    // Create new player at volume 0
    const newPlayer = createAudioPlayer({ uri: newUri });
    newPlayer.loop = true;
    newPlayer.volume = 0;

    // Subscribe new player to status updates
    soundscapeSubRef.current = newPlayer.addListener('playbackStatusUpdate', (status) => {
      setSoundscapeState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    // Start playing new sound
    newPlayer.play();

    // Fade out old, fade in new simultaneously
    const steps = 15;
    const stepDuration = duration / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(() => {
        currentStep++;
        const progress = currentStep / steps;

        // Fade in new
        newPlayer.volume = 0.6 * progress;

        // Fade out old
        if (oldPlayer) {
          try {
            oldPlayer.volume = 0.6 * (1 - progress);
          } catch {
            // Old player may already be removed
          }
        }

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

          // Cleanup old
          if (oldSub) {
            try { oldSub.remove(); } catch { /* ignore */ }
          }
          if (oldPlayer) {
            try { oldPlayer.remove(); } catch { /* ignore */ }
          }

          soundscapeRef.current = newPlayer;
          soundscapeVolumeRef.current = 0.6;
          resolve();
        }
      }, stepDuration);
    });
  }, []);

  // Cleanup all audio
  const cleanup = useCallback(async () => {
    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    if (narrationSubRef.current) {
      try { narrationSubRef.current.remove(); } catch { /* ignore */ }
      narrationSubRef.current = null;
    }
    if (narrationRef.current) {
      try { narrationRef.current.remove(); } catch { /* ignore */ }
      narrationRef.current = null;
    }

    if (soundscapeSubRef.current) {
      try { soundscapeSubRef.current.remove(); } catch { /* ignore */ }
      soundscapeSubRef.current = null;
    }
    if (soundscapeRef.current) {
      try { soundscapeRef.current.remove(); } catch { /* ignore */ }
      soundscapeRef.current = null;
    }

    setNarrationState({ isPlaying: false, positionMs: 0, durationMs: 0 });
    setSoundscapeState({ isPlaying: false, positionMs: 0, durationMs: 0 });
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanup();
    };
  }, [cleanup]);

  return {
    narrationState,
    loadNarration,
    playNarration,
    pauseNarration,
    seekNarration,
    setNarrationVolume,
    soundscapeState,
    loadSoundscape,
    playSoundscape,
    pauseSoundscape,
    setSoundscapeVolume,
    crossfadeSoundscape,
    fadeOutSoundscape,
    cleanup,
  };
}

import { useEffect, useState, useRef, useCallback, useMemo } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Dimensions,
  TouchableOpacity,
} from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import * as Haptics from 'expo-haptics';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  runOnJS,
  Easing,
} from 'react-native-reanimated';
import { scheduleOnRN } from 'react-native-worklets';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import { useReaderData } from '@/hooks/useBookData';
import { useReadingProgress, useAutoSaveProgress } from '@/hooks/useReadingProgress';
import { useAudioManager } from '@/hooks/useAudioManager';
import { useThemeColors, fonts } from '@/lib/theme';
import { ReaderTopBar } from '@/components/ReaderTopBar';
import { AudioControls } from '@/components/AudioControls';
import { SwipePageIndicator } from '@/components/SwipePageIndicator';
import { SkiaPageLayer } from '@/components/reader/SkiaPageLayer';
import { LiquidPageIndicator } from '@/components/reader/LiquidPageIndicator';
import { EdgeTapZones } from '@/components/reader/EdgeTapZones';
import { ReaderSkeleton } from '@/components/Skeleton';
import { GestureTutorial, hasSeenGestureTutorial, markGestureTutorialSeen } from '@/components/reader/GestureTutorial';
import type { PageData } from '@/types';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');
const SWIPE_THRESHOLD = SCREEN_HEIGHT * 0.18;
const VELOCITY_THRESHOLD = 500;

// easeOutExpo bezier — starts fast, decelerates very smoothly (Lenis feel)
const EASE_OUT_EXPO = Easing.bezier(0.16, 1, 0.3, 1);

// easeOutQuart for snap-back (cancelled swipe) — slightly less dramatic
const EASE_OUT_QUART = Easing.bezier(0.25, 1, 0.5, 1);

const UI_ANIMATION_DURATION = 300;

export default function ReaderScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const colors = useThemeColors();
  const bookId = id ?? '';

  // Data
  const { data: readerData, isLoading, error, refetch } = useReaderData(bookId);
  const { data: savedProgress } = useReadingProgress(bookId);

  // State
  const [activeIndex, setActiveIndex] = useState(0);
  const [showSettings, setShowSettings] = useState(false);
  const [isUIVisible, setIsUIVisible] = useState(true);
  const [showTutorial, setShowTutorial] = useState(false);
  const progressRestoredRef = useRef(false);
  const tutorialCheckedRef = useRef(false);

  // Derived
  const pages = useMemo(
    () => [...(readerData?.pages ?? [])].sort((a, b) => a.pageNumber - b.pageNumber),
    [readerData?.pages]
  );
  const totalPages = pages.length;
  const currentPage = pages[activeIndex]?.pageNumber ?? 1;
  const pageData: PageData | undefined = pages[activeIndex];
  const progressPercent = totalPages > 0 ? ((activeIndex + 1) / totalPages) * 100 : 0;

  // Audio
  const {
    isNarrationActive,
    isSoundscapeActive,
    narrationState,
    soundscapeState,
    isTransitioning,
    toggleNarration,
    toggleSoundscape,
    cleanup,
  } = useAudioManager({ 
    pageData, 
    bookId,
    pageNumber: currentPage 
  });

  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl;
  const soundscapeUrl = soundscapeAssignment?.audioUrl;

  // ===============================================================
  // NARRATION POSITION — SharedValue bridge
  // Sync positionMs from the JS audio hook into a SharedValue so
  // SkiaPageLayer can compute word indices on the UI thread.
  // ===============================================================

  const narrationPositionShared = useSharedValue(0);

  useEffect(() => {
    narrationPositionShared.value = narrationState.positionMs;
  }, [narrationState.positionMs, narrationPositionShared]);

  // ===============================================================
  // REANIMATED GESTURE PAGER
  // ===============================================================

  const scrollOffset = useSharedValue(0); // continuous, -pageIndex * SCREEN_HEIGHT at rest
  const activeIndexShared = useSharedValue(0);
  const baseScrollOffset = useSharedValue(0); // captures position at gesture start

  // scheduleOnRN replaces runOnJS — the Reanimated v4 / worklets API
  const updateActiveIndex = useCallback(
    (newIndex: number) => {
      setActiveIndex(newIndex);
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    },
    []
  );

  const toggleUI = useCallback(() => {
    setIsUIVisible((prev) => {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      return !prev;
    });
  }, []);

  const panGesture = Gesture.Pan()
    .activeOffsetY([-12, 12])
    .onBegin(() => {
      baseScrollOffset.value = scrollOffset.value;
    })
    .onUpdate((e) => {
      const rawOffset = baseScrollOffset.value + e.translationY;
      const minOffset = -(totalPages - 1) * SCREEN_HEIGHT;
      const maxOffset = 0;

      if (rawOffset > maxOffset) {
        scrollOffset.value = maxOffset + (rawOffset - maxOffset) * 0.15;
      } else if (rawOffset < minOffset) {
        scrollOffset.value = minOffset + (rawOffset - minOffset) * 0.15;
      } else {
        scrollOffset.value = rawOffset;
      }
    })
    .onEnd((e) => {
      const idx = activeIndexShared.value;
      const totalPgs = totalPages;

      const swipedUp = e.translationY < -SWIPE_THRESHOLD || e.velocityY < -VELOCITY_THRESHOLD;
      const swipedDown = e.translationY > SWIPE_THRESHOLD || e.velocityY > VELOCITY_THRESHOLD;

      let destIndex = idx;
      if (swipedUp && idx < totalPgs - 1) {
        destIndex = idx + 1;
      } else if (swipedDown && idx > 0) {
        destIndex = idx - 1;
      }

      const destOffset = -destIndex * SCREEN_HEIGHT;

      const distance = Math.abs(destOffset - scrollOffset.value);
      const speed = Math.max(Math.abs(e.velocityY), 100);
      const duration = Math.min(Math.max((distance / speed) * 1000 * 0.6, 280), 520);

      if (destIndex !== idx) {
        activeIndexShared.value = destIndex;
        // v4 worklets API: scheduleOnRN(fn, ...args) replaces runOnJS(fn)(args)
        scheduleOnRN(updateActiveIndex, destIndex);
      }

      scrollOffset.value = withTiming(destOffset, {
        duration,
        easing: destIndex !== idx ? EASE_OUT_EXPO : EASE_OUT_QUART,
      });
    });

  const tapGesture = Gesture.Tap()
    .maxDuration(250)
    .onEnd(() => {
      scheduleOnRN(toggleUI);
    });

  const composedGesture = Gesture.Race(panGesture, tapGesture);

  // ===============================================================
  // PROGRESS
  // ===============================================================

  useAutoSaveProgress({
    bookId,
    currentPage,
    totalPages,
    enabled: !isLoading && totalPages > 0,
  });

  // Restore reading progress
  useEffect(() => {
    if (progressRestoredRef.current || isLoading || !readerData) return;

    if (savedProgress?.currentPage && savedProgress.currentPage > 1 && savedProgress.currentPage <= totalPages) {
      const idx = pages.findIndex((p) => p.pageNumber === savedProgress.currentPage);
      if (idx > 0) {
        setActiveIndex(idx);
        activeIndexShared.value = idx;
        scrollOffset.value = -idx * SCREEN_HEIGHT;
      }
    }
    progressRestoredRef.current = true;
  }, [savedProgress, isLoading, readerData, totalPages, pages, activeIndexShared, scrollOffset]);

  // ===============================================================
  // GESTURE TUTORIAL (FTUE)
  // ===============================================================

  useEffect(() => {
    if (tutorialCheckedRef.current || isLoading) return;

    const checkTutorial = async () => {
      const hasSeen = await hasSeenGestureTutorial();
      if (!hasSeen) {
        setShowTutorial(true);
      }
      tutorialCheckedRef.current = true;
    };

    checkTutorial();
  }, [isLoading]);

  const handleTutorialComplete = useCallback(() => {
    setShowTutorial(false);
    markGestureTutorialSeen();
  }, []);

  // ===============================================================
  // CLEANUP
  // ===============================================================

  useEffect(() => {
    return () => {
      cleanup();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleClose = useCallback(async () => {
    await cleanup();
    router.back();
  }, [router, cleanup]);

  // ===============================================================
  // EDGE TAP NAVIGATION
  // ===============================================================

  const goToPreviousPage = useCallback(() => {
    if (activeIndex > 0) {
      const newIndex = activeIndex - 1;
      setActiveIndex(newIndex);
      activeIndexShared.value = newIndex;
      scrollOffset.value = withTiming(-newIndex * SCREEN_HEIGHT, {
        duration: 400,
        easing: EASE_OUT_EXPO,
      });
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
  }, [activeIndex, activeIndexShared, scrollOffset]);

  const goToNextPage = useCallback(() => {
    if (activeIndex < totalPages - 1) {
      const newIndex = activeIndex + 1;
      setActiveIndex(newIndex);
      activeIndexShared.value = newIndex;
      scrollOffset.value = withTiming(-newIndex * SCREEN_HEIGHT, {
        duration: 400,
        easing: EASE_OUT_EXPO,
      });
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
  }, [activeIndex, totalPages, activeIndexShared, scrollOffset]);

  // ===============================================================
  // UI VISIBILITY — Reanimated v4 CSS-style transitions
  // These replace the useAnimatedStyle + withTiming pattern for
  // state-driven show/hide. Fabric animates the style diff natively.
  // ===============================================================

  const topBarAnimatedStyle = useAnimatedStyle(() => ({
    opacity: withTiming(isUIVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
  }));

  const audioControlsAnimatedStyle = useAnimatedStyle(() => ({
    opacity: withTiming(isUIVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
  }));

  const tapHintAnimatedStyle = useAnimatedStyle(() => ({
    opacity: withTiming(isUIVisible ? 0 : 0.4, { duration: UI_ANIMATION_DURATION }),
  }));

  // ===============================================================
  // VISIBLE PAGES (virtualization window of +/-1)
  // ===============================================================

  const visiblePages = useMemo(() => {
    const start = Math.max(0, activeIndex - 1);
    const end = Math.min(pages.length - 1, activeIndex + 1);
    const result: { page: typeof pages[0]; index: number }[] = [];
    for (let i = start; i <= end; i++) {
      result.push({ page: pages[i], index: i });
    }
    return result;
  }, [pages, activeIndex]);

  const isNarrationPlaying = isNarrationActive && narrationState.isPlaying;

  // ===============================================================
  // RENDER
  // ===============================================================

  if (isLoading) {
    return <ReaderSkeleton />;
  }

  if (error || !readerData) {
    return (
      <View style={[styles.centered, { backgroundColor: colors.readerBg }]}>
        <Text style={[styles.errorTitle, { color: colors.error, fontFamily: fonts.sans }]}>
          Oops!
        </Text>
        <Text style={[styles.errorText, { color: colors.readerTextSecondary, fontFamily: fonts.sans }]}>
          {error?.message || 'Book not found'}
        </Text>
        <View style={styles.errorButtonsContainer}>
          <TouchableOpacity
            style={[styles.primaryButton, { backgroundColor: colors.readerProgressBarFill }]}
            onPress={() => refetch()}
            activeOpacity={0.8}
          >
            <Text style={[styles.primaryButtonText, { color: colors.readerBg, fontFamily: fonts.sans }]}>
              Try Again
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[styles.secondaryButton, { borderColor: colors.readerTextSecondary }]}
            onPress={() => router.back()}
            activeOpacity={0.8}
          >
            <Text style={[styles.secondaryButtonText, { color: colors.readerTextSecondary, fontFamily: fonts.sans }]}>
              Go Back
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  return (
    <View style={[styles.container, { backgroundColor: colors.readerBg }]}>
      <GestureDetector gesture={composedGesture}>
        <View style={styles.pagerContainer}>
          {visiblePages.map(({ page, index }) => (
            <SkiaPageLayer
              key={page.id}
              page={page}
              pageIndex={index}
              activeIndex={activeIndex}
              scrollOffset={scrollOffset}
              activeIndexShared={activeIndexShared}
              narrationPositionMs={narrationPositionShared}
              isNarrationPlaying={isNarrationPlaying}
              totalPages={pages.length}
            />
          ))}
        </View>
      </GestureDetector>

      {/* Liquid Skia pagination — right edge, driven from scrollOffset SharedValue */}
      <LiquidPageIndicator
        totalPages={totalPages}
        scrollOffset={scrollOffset}
        isVisible={isUIVisible}
      />

      {/* Floating UI - Top bar */}
      <Animated.View
        style={[styles.topBarContainer, topBarAnimatedStyle]}
        pointerEvents={isUIVisible ? 'auto' : 'none'}
      >
        <ReaderTopBar
          progressPercent={progressPercent}
          currentPage={currentPage}
          totalPages={totalPages}
          onClose={handleClose}
          onSettings={() => setShowSettings(true)}
        />
      </Animated.View>

      {/* Floating UI - Audio controls */}
      <Animated.View
        style={[styles.audioControlsContainer, audioControlsAnimatedStyle]}
        pointerEvents={isUIVisible ? 'auto' : 'none'}
      >
        <AudioControls
          hasNarration={!!narrationUrl}
          hasSoundscape={!!soundscapeUrl}
          isNarrationPlaying={isNarrationActive && narrationState.isPlaying}
          isSoundscapePlaying={isSoundscapeActive && soundscapeState.isPlaying}
          onToggleNarration={toggleNarration}
          onToggleSoundscape={toggleSoundscape}
        />
      </Animated.View>

      <SwipePageIndicator visible={isUIVisible && activeIndex === 0 && totalPages > 1} />

      {/* Edge Tap Zones - only visible when UI is hidden */}
      {!isUIVisible && (
        <EdgeTapZones
          onPrevious={goToPreviousPage}
          onNext={goToNextPage}
          isVisible={!isUIVisible}
        />
      )}

      {/* Tap hint when UI is hidden */}
      <Animated.View style={[styles.tapHintContainer, tapHintAnimatedStyle]} pointerEvents="none">
        <View style={styles.tapHintPill}>
          <Text style={styles.tapHintText}>
            Tap to show controls
          </Text>
        </View>
      </Animated.View>

      <GestureTutorial
        visible={showTutorial}
        onComplete={handleTutorialComplete}
      />
    </View>
  );
}

